//! The generated programs. Each is written once in WGSL (`shaders/NAME.wgsl`, with the shared module
//! `shaders/shared.wgsl` ahead of it) and generated by `cupertino-gpu-shaders` into GLSL ES 3.00, SPIR-V and the
//! names its blocks and samplers are bound by (`shaders/generated/`). The generated files are committed; a test of
//! that crate fails when they differ from a fresh generation.

/// One program for every backend.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ShaderSource {
    pub name: &'static str,
    /// GLSL ES 3.00 of `vs_main`.
    pub vertex_glsl: &'static str,
    /// GLSL ES 3.00 of `fs_main`.
    pub fragment_glsl: &'static str,
    /// SPIR-V 1.0 with both entry points, little-endian words.
    pub spirv: &'static [u8],
    /// The binding names, one per line (see [`ShaderSource::bindings`]).
    pub bindings_text: &'static str,
}

/// Where the GLSL of a program reads a WGSL binding.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum NamedBinding {
    /// The uniform block named `block` holds group `group`, binding `binding`.
    Uniform {
        group: u32,
        binding: u32,
        block: String,
    },
    /// The sampler uniform `name` samples the texture at `group`, `binding` through the sampler at `sampler`
    /// (group, binding), or reads it without one.
    Texture {
        group: u32,
        binding: u32,
        sampler: Option<(u32, u32)>,
        name: String,
    },
}

impl ShaderSource {
    /// The bindings by name, both stages'.
    pub fn bindings(&self) -> Vec<NamedBinding> {
        let number = |s: &str| s.parse::<u32>().ok();
        self.bindings_text
            .lines()
            .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
            .filter_map(|l| {
                let f: Vec<&str> = l.split_whitespace().collect();
                match f.as_slice() {
                    ["uniform", g, b, _stage, block] => Some(NamedBinding::Uniform {
                        group: number(g)?,
                        binding: number(b)?,
                        block: (*block).to_owned(),
                    }),
                    ["texture", g, b, sg, sb, _stage, name] => Some(NamedBinding::Texture {
                        group: number(g)?,
                        binding: number(b)?,
                        sampler: number(sg).zip(number(sb)),
                        name: (*name).to_owned(),
                    }),
                    _ => None,
                }
            })
            .collect()
    }
}

macro_rules! program {
    ($(#[$doc:meta])* $id:ident, $name:literal) => {
        $(#[$doc])*
        pub const $id: ShaderSource = ShaderSource {
            name: $name,
            vertex_glsl: include_str!(concat!("../shaders/generated/", $name, ".vert.glsl")),
            fragment_glsl: include_str!(concat!("../shaders/generated/", $name, ".frag.glsl")),
            spirv: include_bytes!(concat!("../shaders/generated/", $name, ".spv")),
            bindings_text: include_str!(concat!("../shaders/generated/", $name, ".bindings")),
        };
    };
}

program!(
    /// Rounded rectangles filled with coverage from the shared distance, one instance each.
    SHAPE,
    "shape"
);
program!(
    /// A texture over the whole target through a sampler.
    BLIT,
    "blit"
);
program!(
    /// A texture copied over the target texel for texel, unscaled from its first pixel.
    BLIT_TEXELS,
    "blit_texels"
);
program!(
    /// One 2x box halving of the blur pyramid.
    BLUR_HALVE,
    "blur_halve"
);
program!(
    /// One separable pass of the blur's Gaussian.
    BLUR_GAUSS,
    "blur_gauss"
);
program!(
    /// One grey level dithered by the pixel it is stored in.
    DITHER_FILL,
    "dither_fill"
);
program!(
    /// The toolkit renderer's coverage draws: shapes, glyph coverage and path masks, tinted, under clips.
    UI_FILL,
    "ui_fill"
);
program!(
    /// The toolkit renderer's colour draws: colour glyphs, layers and images, under clips.
    UI_TEXTURE,
    "ui_texture"
);
program!(
    /// The toolkit renderer's last step of a layer's blur or shadow.
    UI_EFFECT,
    "ui_effect"
);
program!(
    /// Test program: shared distance and coverage at given points.
    PROBE_COVERAGE,
    "probe_coverage"
);
program!(
    /// Test program: shared drop and inner shadows at given points.
    PROBE_SHADOW,
    "probe_shadow"
);
program!(
    /// Test program: the shared gradient rule at given parameters.
    PROBE_GRADIENT,
    "probe_gradient"
);
program!(
    /// Test program: the shared dither at given pixels.
    PROBE_DITHER,
    "probe_dither"
);

/// Every program.
pub const ALL: &[ShaderSource] = &[
    SHAPE,
    BLIT,
    BLIT_TEXELS,
    BLUR_HALVE,
    BLUR_GAUSS,
    DITHER_FILL,
    UI_FILL,
    UI_TEXTURE,
    UI_EFFECT,
    PROBE_COVERAGE,
    PROBE_SHADOW,
    PROBE_GRADIENT,
    PROBE_DITHER,
];

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_binding_names_of_a_program_are_read_by_group_and_binding() {
        assert_eq!(
            BLIT.bindings(),
            vec![NamedBinding::Texture {
                group: 0,
                binding: 1,
                sampler: Some((0, 2)),
                name: "_group_0_binding_1_fs".into()
            }]
        );
        assert!(BLUR_GAUSS.bindings().contains(&NamedBinding::Texture {
            group: 0,
            binding: 1,
            sampler: None,
            name: "_group_0_binding_1_fs".into()
        }));
        assert!(SHAPE.bindings().iter().any(|b| matches!(
            b,
            NamedBinding::Uniform {
                group: 0,
                binding: 0,
                ..
            }
        )));
        for program in ALL {
            assert!(
                program.vertex_glsl.starts_with("#version 300 es"),
                "{}",
                program.name
            );
            assert_eq!(program.spirv.len() % 4, 0);
        }
    }

    #[test]
    fn every_generated_program_is_listed() {
        let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/shaders");
        let mut names: Vec<String> = std::fs::read_dir(dir)
            .unwrap()
            .filter_map(|e| e.ok()?.file_name().into_string().ok())
            .filter_map(|n| n.strip_suffix(".wgsl").map(str::to_owned))
            .filter(|n| n != "shared")
            .collect();
        names.sort();
        let mut listed: Vec<String> = ALL.iter().map(|p| p.name.to_owned()).collect();
        listed.sort();
        assert_eq!(names, listed);
    }
}
